INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-03-18-germany-geba-peppol-addressing', 'en', 'Germany introduces GEBA addressing for its growing Peppol network', 'Germany has introduced the German Electronic Business Address (GEBA), a national addressing scheme for the Peppol network, as Peppol-based routing becomes more important ahead of the January 2027 issuance mandate.', '<h3>🇩🇪 Germany introduces GEBA addressing for its growing Peppol network</h3>
<p>Germany has rolled out the German Electronic Business Address (GEBA), a national identifier scheme for routing invoices over the Peppol network. This matters more in Germany than it might in a country with a central clearance platform: Germany''s model is fully decentralised, with no government platform validating or routing invoices at all. Compliance, in practice, rests heavily on the recipient''s own validation rules and buyer-specific requirements — which makes having a reliable, standardised way to actually address and locate a trading partner on the network a genuinely load-bearing piece of infrastructure, not a minor technical detail.</p>
<p>GEBA sits alongside Germany''s existing e-invoicing formats — XRechnung and ZUGFeRD, both built to the EN 16931 European standard — giving businesses using Peppol BIS 3.0 a proper German-specific addressing layer rather than relying on workarounds. For companies already active on Peppol in other markets, this is a relatively small integration change; for those only now building out their German invoicing setup, it''s one more piece worth getting right early, given how much of the compliance burden in Germany''s model sits with correctly identifying and validating your counterpart rather than with a central authority doing it for you.</p>
<p><strong>What this means for your team:</strong> if you''re building or updating Peppol connectivity for German trading partners, confirm your setup correctly resolves GEBA identifiers rather than assuming your existing non-German Peppol configuration will carry over unchanged. Given Germany''s decentralised model puts more validation responsibility on each business directly, addressing errors here tend to surface as quiet, ongoing friction with specific partners rather than a single obvious failure.</p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-03-17-germany-practical-readiness-guidance', '2026-03-17', '2026-03', 'Fresh practical guidance for German businesses spells out a distinction worth taking seriously: an invoice with a format or syntax error isn''t just a flawed e-invoice, it''s treated as not being an e-invoice at all, with real VAT-deduction consequences.', '<h3>🇩🇪 New practical guidance clarifies what ''e-invoice ready'' actually means for German businesses</h3>
<p>New practical guidance aimed at businesses and their tax advisers draws a distinction worth taking seriously ahead of the January 2027 issuance mandate: a genuine format or syntax error — an invoice that doesn''t structurally comply with EN 16931 — isn''t treated as a flawed e-invoice, it''s treated as not being an e-invoice at all. That''s a materially different, more serious outcome, since a document that fails to even qualify carries real consequences for input VAT deduction, not merely a correction request.</p>
<p>Business-rule violations are treated as a distinct, separate category from pure syntax errors — problems with critical VAT-relevant content within an otherwise structurally valid invoice. The guidance is also explicit on a point worth internalising directly: while validation tools are expected to be used, running an invoice through one doesn''t shift final responsibility away from the issuing business. The entrepreneur retains that responsibility regardless of which tool or service was used to check the document beforehand.</p>
<p><strong>What this means for your team:</strong> don''t treat "we ran it through a validator" as equivalent to "we''re compliant" — the guidance is direct that the two aren''t the same thing. Given Germany''s standard retention period runs 8 years for invoices generally and 10 years for core accounting records under GoBD, it''s worth confirming now, well before the 2027 issuance deadline, that your archiving setup can actually produce a validated, structurally-compliant invoice on demand for the full retention window — not just that it stores a copy of whatever was sent.</p>', 'https://www.bundesfinanzministerium.de/Content/DE/FAQ/e-rechnung.html', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-03-17-germany-practical-readiness-guidance', id FROM countries WHERE name_en = 'Germany';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-03-17-germany-practical-readiness-guidance', 'en', 'New practical guidance clarifies what ''e-invoice ready'' actually means for German businesses', 'Fresh practical guidance for German businesses spells out a distinction worth taking seriously: an invoice with a format or syntax error isn''t just a flawed e-invoice, it''s treated as not being an e-invoice at all, with real VAT-deduction consequences.', '<h3>🇩🇪 New practical guidance clarifies what ''e-invoice ready'' actually means for German businesses</h3>
<p>New practical guidance aimed at businesses and their tax advisers draws a distinction worth taking seriously ahead of the January 2027 issuance mandate: a genuine format or syntax error — an invoice that doesn''t structurally comply with EN 16931 — isn''t treated as a flawed e-invoice, it''s treated as not being an e-invoice at all. That''s a materially different, more serious outcome, since a document that fails to even qualify carries real consequences for input VAT deduction, not merely a correction request.</p>
<p>Business-rule violations are treated as a distinct, separate category from pure syntax errors — problems with critical VAT-relevant content within an otherwise structurally valid invoice. The guidance is also explicit on a point worth internalising directly: while validation tools are expected to be used, running an invoice through one doesn''t shift final responsibility away from the issuing business. The entrepreneur retains that responsibility regardless of which tool or service was used to check the document beforehand.</p>
<p><strong>What this means for your team:</strong> don''t treat "we ran it through a validator" as equivalent to "we''re compliant" — the guidance is direct that the two aren''t the same thing. Given Germany''s standard retention period runs 8 years for invoices generally and 10 years for core accounting records under GoBD, it''s worth confirming now, well before the 2027 issuance deadline, that your archiving setup can actually produce a validated, structurally-compliant invoice on demand for the full retention window — not just that it stores a copy of whatever was sent.</p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-06-10-germany-rollout-on-track-confirmed', '2026-06-10', '2026-06', 'At June''s E-Invoicing Summit in Berlin, industry representatives and policymakers confirmed Germany''s B2B e-invoicing rollout remains on schedule, with no postponement currently expected for the January 2027 issuance mandate.', '<h3>🇩🇪 Industry and policymakers confirm the January 2027 rollout remains on track</h3>
<p>At the E-Invoicing Summit in Berlin this June, industry representatives and policymakers directly addressed a question that''s been circulating for a while: whether the January 2027 issuance mandate might slip. The answer was a clear no — mandatory issuance of structured e-invoices for businesses with prior-year turnover above €800,000 remains on schedule for 1 January 2027, with no postponement currently expected. For businesses that had been holding off on committing engineering time on the assumption a delay might materialise, that assumption no longer has much to stand on.</p>
<p>Germany''s phased approach means the receiving obligation has actually been in force since 1 January 2025 — every domestic business must already be able to receive, validate, and store structured e-invoices, regardless of whether they''re yet required to issue them. The gap many businesses are still working through is the difference between merely being able to receive an e-invoice and having fully standardised issuing, validation, and partner-onboarding processes in place — the second of these is what the 2027 deadline actually tests, and it''s a meaningfully bigger lift than the receiving obligation already in force.</p>
<p><strong>What this means for your team:</strong> if your business crosses the €800,000 threshold, treat 2026 as the year to close the gap between "we can technically receive an e-invoice" and "we can reliably issue, validate, and archive them at scale" — the confirmed absence of a delay means there''s no extra runway being handed to anyone. Businesses below the threshold get until January 2028, but the receiving obligation already applies today regardless of size, so that distinction only affects the issuing side.</p>', 'https://www.bundesfinanzministerium.de/Content/DE/FAQ/e-rechnung.html', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-06-10-germany-rollout-on-track-confirmed', id FROM countries WHERE name_en = 'Germany';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-10-germany-rollout-on-track-confirmed', 'en', 'Industry and policymakers confirm the January 2027 rollout remains on track', 'At June''s E-Invoicing Summit in Berlin, industry representatives and policymakers confirmed Germany''s B2B e-invoicing rollout remains on schedule, with no postponement currently expected for the January 2027 issuance mandate.', '<h3>🇩🇪 Industry and policymakers confirm the January 2027 rollout remains on track</h3>
<p>At the E-Invoicing Summit in Berlin this June, industry representatives and policymakers directly addressed a question that''s been circulating for a while: whether the January 2027 issuance mandate might slip. The answer was a clear no — mandatory issuance of structured e-invoices for businesses with prior-year turnover above €800,000 remains on schedule for 1 January 2027, with no postponement currently expected. For businesses that had been holding off on committing engineering time on the assumption a delay might materialise, that assumption no longer has much to stand on.</p>
<p>Germany''s phased approach means the receiving obligation has actually been in force since 1 January 2025 — every domestic business must already be able to receive, validate, and store structured e-invoices, regardless of whether they''re yet required to issue them. The gap many businesses are still working through is the difference between merely being able to receive an e-invoice and having fully standardised issuing, validation, and partner-onboarding processes in place — the second of these is what the 2027 deadline actually tests, and it''s a meaningfully bigger lift than the receiving obligation already in force.</p>
<p><strong>What this means for your team:</strong> if your business crosses the €800,000 threshold, treat 2026 as the year to close the gap between "we can technically receive an e-invoice" and "we can reliably issue, validate, and archive them at scale" — the confirmed absence of a delay means there''s no extra runway being handed to anyone. Businesses below the threshold get until January 2028, but the receiving obligation already applies today regardless of size, so that distinction only affects the issuing side.</p>');
